113.     @Override
114.     public Object getContent() throws XMLDBException {
115.         if (content != null) {            
116.             return content;
117.         }
118. 
119.         // Case 1: content is an external DOM node
120.         else if (root != null && !(root instanceof NodeValue)) {
121.             try(final StringWriter writer = new StringWriter()) {
122.                 final DOMSerializer serializer = new DOMSerializer(writer, getProperties());
123.                 try {
124.                     serializer.serialize(root);
125.                     content = writer.toString();
126.                 } catch (final TransformerException e) {
127.                     throw new XMLDBException(ErrorCodes.INVALID_RESOURCE, e.getMessage(), e);
128.                 }
129.                 return content;
130.             } catch(final IOException e) {
131.                 throw new XMLDBException(ErrorCodes.UNKNOWN_ERROR, e.getMessage(), e);
132.             }
133. 
134.         // Case 2: content is an atomic value
135.         } else if (value != null) {
136.             try {
137.                 if (Type.subTypeOf(value.getType(),Type.STRING)) {
138.                     return ((StringValue)value).getStringValue(true);
139.                 } else {
140.                     return value.getStringValue();
141.                 }
142.             } catch (final XPathException e) {
143.                 throw new XMLDBException(ErrorCodes.INVALID_RESOURCE, e.getMessage(), e);
144.             }
145. 
146.         // Case 3: content is a file
147.         } else if (file != null) {
148.             try {
149.                 content = XMLUtil.readFile(file);
150.                 return content;
151.             } catch (final IOException e) {
152.                 throw new XMLDBException(ErrorCodes.VENDOR_ERROR, "error while reading resource contents", e);
153.             }
154. 
155.         // Case 4: content is an input source
156.         } else if (inputSource != null) {
157.             try {
158.                 content = XMLUtil.readFile(inputSource);
159.                 return content;
160.             } catch (final IOException e) {
161.                 throw new XMLDBException(ErrorCodes.VENDOR_ERROR, "error while reading resource contents", e);
162.             }
163. 
164.         // Case 5: content is a document or internal node, we MUST serialize it
165.         } else {
166.             content = withDb((broker, transaction) -> {
167.                 final Serializer serializer = broker.borrowSerializer();
168. 
169.                 try {
170.                     serializer.setUser(user);
171.                     serializer.setProperties(getProperties());
172. 
173.                     if (root != null) {
174.                         return serialize(broker, saxSerializer -> saxSerializer.toSAX((NodeValue) root));
175.                     } else if (proxy != null) {
176.                         return serialize(broker, saxSerializer -> saxSerializer.toSAX(proxy));
177.                     } else {
178.                         return this.<String>read(broker, transaction).apply((document, broker1, transaction1) -> {
179.                             try {
180.                                 return serialize(broker, saxSerializer -> saxSerializer.toSAX(document));
181.                             } catch (final SAXException e) {
182.                                 throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
183.                             }
184.                         });
185.                     }
186.                 } catch (final SAXException e) {
187.                     throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
188.                 } finally {
189.                     broker.returnSerializer(serializer);
190.                 }
191.             });
192.             return content;
193.         }
194.     }
