196.     @Override
197.     public void getContentAsStream(OutputStream os) throws XMLDBException {
198.         try {
199.             if (content != null) {
200.                 os.write(content.getBytes(UTF_8));
201. 
202.             // Case 1: content is an external DOM node
203.             } else if (root != null && !(root instanceof NodeValue)) {
204.                 try(OutputStreamWriter writer = new OutputStreamWriter(os, UTF_8)) {
205.                     final DOMSerializer serializer = new DOMSerializer(writer, getProperties());
206.                     try {
207.                         serializer.serialize(root);
208.                         content = writer.toString();
209.                     } catch (final TransformerException e) {
210.                         throw new XMLDBException(ErrorCodes.INVALID_RESOURCE, e.getMessage(), e);
211.                     }
212.                 }
213. 
214.             // Case 2: content is an atomic value
215.             } else if (value != null) {
216.                 try {
217.                     if (Type.subTypeOf(value.getType(),Type.STRING)) {
218.                         os.write(((StringValue)value).getStringValue(true).getBytes(UTF_8));
219.                     } else {
220.                         os.write(value.getStringValue().getBytes(UTF_8));
221.                     }
222.                 } catch (final XPathException e) {
223.                     throw new XMLDBException(ErrorCodes.INVALID_RESOURCE, e.getMessage(), e);
224.                 }
225. 
226.             // Case 3: content is a file
227.             } else if (file != null) {
228.                 Files.copy(file, os);
229.             
230.               // Case 4: content is an input source
231.             } else if (inputSource != null) {
232.                 IOUtils.copy(inputSource.getByteStream(), os);
233. 
234.               // Case 5: content is a document or internal node, we MUST serialize it
235.             } else {
236.                 content = withDb((broker, transaction) -> {
237.                     final Serializer serializer = broker.getSerializer();
238.                     serializer.setUser(user);
239.                     try {
240.                         serializer.setProperties(getProperties());
241.                         if (root != null) {
242.                             return serialize(broker, saxSerializer -> saxSerializer.toSAX((NodeValue) root));
243.                         } else if (proxy != null) {
244.                             return serialize(broker, saxSerializer -> saxSerializer.toSAX(proxy));
245.                         } else {
246.                             return this.<String>read(broker, transaction).apply((document, broker1, transaction1) -> {
247.                                 try {
248.                                     return serialize(broker, saxSerializer -> saxSerializer.toSAX(document));
249.                                 } catch (final SAXException e) {
250.                                     throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
251.                                 }
252.                             });
253.                         }
254.                     } catch (final SAXException e) {
255.                         throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
256.                     }
257.                });
258.                os.write(content.getBytes(UTF_8));
259.             }
260.         } catch (IOException e) {
261.             throw new XMLDBException(ErrorCodes.UNKNOWN_ERROR, e.getMessage(), e);
262.         }
263.     }
