265.     private String serialize(final DBBroker broker, final ConsumerE<Serializer, SAXException> toSaxFunction) throws SAXException, IOException {
266.         final Serializer serializer = broker.borrowSerializer();
267.         SAXSerializer saxSerializer = null;
268.         try {
269.             serializer.setUser(user);
270.             serializer.setProperties(getProperties());
271.             saxSerializer = (SAXSerializer) SerializerPool.getInstance().borrowObject(SAXSerializer.class);
272. 
273.             try (final StringWriter writer = new StringWriter()) {
274.                 saxSerializer.setOutput(writer, getProperties());
275.                 serializer.setSAXHandlers(saxSerializer, saxSerializer);
276. 
277.                 toSaxFunction.accept(serializer);
278. 
279.                 writer.flush();
280.                 return writer.toString();
281.             }
282.         } finally {
283.             if (saxSerializer != null) {
284.                 SerializerPool.getInstance().returnObject(saxSerializer);
285.             }
286.             broker.returnSerializer(serializer);
287.         }
288.     }
