290.     @Override
291.     public Node getContentAsDOM() throws XMLDBException {
292.         final Node result;
293.         if (root != null) {
294.             if(root instanceof NodeImpl) {
295.                 withDb((broker, transaction) -> {
296.                     ((NodeImpl)root).expand();
297.                     return null;
298.                 });
299.             }
300.             result = root;
301.         } else if (value != null) {
302.             throw new XMLDBException(ErrorCodes.VENDOR_ERROR, "cannot return an atomic value as DOM node");
303.         } else {
304.             result = read((document, broker, transaction) -> {
305.                 if (proxy != null) {
306.                     return document.getNode(proxy);
307.                 } else {
308.                     // <frederic.glorieux@ajlsm.com> return a full to get root PI and comments
309.                     return document;
310.                 }
311.             });
312.         }
313. 
314.         return exportInternalNode(result);
315.     }
