317.     /**
318.      * Provides a safe export of an internal persistent DOM
319.      * node from eXist via the Local XML:DB API.
320.      *
321.      * This is done by providing a cglib Proxy object that only implements
322.      * the appropriate W3C DOM interface. This helps prevent the
323.      * XML:DB Local API from leaking implementation through
324.      * its abstractions.
325.      */
326.     private Node exportInternalNode(final Node node) {
327.         final Optional<Class<? extends Node>> domClazz = getW3cNodeInterface(node.getClass());
328.         if(!domClazz.isPresent()) {
329.             throw new IllegalArgumentException("Provided node does not implement org.w3c.dom");
330.         }
331. 
332.         final Enhancer enhancer = new Enhancer();
333.         enhancer.setSuperclass(domClazz.get());
334.         final Class[] interfaceClasses;
335.         if (node instanceof StoredNode) {
336.             interfaceClasses = new Class[]{domClazz.get(), StoredNodeIdentity.class};
337.         } else if (node instanceof org.exist.dom.memtree.NodeImpl) {
338.             interfaceClasses = new Class[]{domClazz.get(), MemtreeNodeIdentity.class};
339.         } else {
340.             interfaceClasses = new Class[] { domClazz.get() };
341.         }
342.         enhancer.setInterfaces(interfaceClasses);
343.         enhancer.setCallback(new DOMMethodInterceptor(node));
344. 
345.         return (Node)enhancer.create();
346.     }
347. 
348.     private Optional<Class<? extends Node>> getW3cNodeInterface(final Class<? extends Node> nodeClazz) {
349.         return Stream.of(nodeClazz.getInterfaces())
350.                 .filter(iface -> iface.getPackage().getName().equals("org.w3c.dom"))
351.                 .findFirst()
352.                 .map(c -> (Class<? extends Node>)c);
353.     }
