355.     private class DOMMethodInterceptor implements MethodInterceptor {
356.         private final Node node;
357. 
358.         public DOMMethodInterceptor(final Node node) {
359.             this.node = node;
360.         }
361. 
362.         @Override
363.         public Object intercept(final Object obj, final Method method, final Object[] args, final MethodProxy proxy) throws Throwable {
364.             /*
365.                 NOTE(AR): we have to take special care of eXist-db's
366.                 persistent and memtree DOM's node equality.
367. 
368.                 For the persistent DOM, we reproduce in the proxy the behaviour taken
369.                 by org.exist.dom.persistent.StoredNode#equals(Object),
370.                 by overriding equals for StoredNode's and then implementing
371.                 a method to retrieve the nodeIds from each side of the equality
372.                 comparison. We have to do this as StoredNode attempts instanceof
373.                 equality which will fail against the proxied objects.
374. 
375.                 For the memtree DOM, we reproduce in the proxy the behaviour taken
376.                 by org.exist.dom.memtree.NodeImpl#equals(Object),
377.                 by overriding equals for memtree.NodeImpl's and then implementing
378.                 a method to retrieve the nodeIds from each side of the equality
379.                 comparison. We have to do this as NodeImpl attempts instanceof and
380.                 reference equality which will fail against the proxied objects.
381.              */
382.             Object domResult = null;
383.             if(method.getName().equals("equals")
384.                     && obj instanceof StoredNodeIdentity
385.                     && args.length == 1 && args[0] instanceof StoredNodeIdentity) {
386.                 final StoredNodeIdentity ni1 = ((StoredNodeIdentity) obj);
387.                 final StoredNodeIdentity ni2 = ((StoredNodeIdentity) args[0]);
388. 
389.                 final Optional<Boolean> niEquals = ni1.getNodeId().flatMap(n1id -> ni2.getNodeId().map(n1id::equals));
390.                 if (niEquals.isPresent()) {
391.                     domResult = niEquals.get();
392.                 }
393.             } else if(method.getName().equals("equals")
394.                         && obj instanceof MemtreeNodeIdentity
395.                         && args.length == 1 && args[0] instanceof MemtreeNodeIdentity) {
396.                     final MemtreeNodeIdentity ni1 = ((MemtreeNodeIdentity) obj);
397.                     final MemtreeNodeIdentity ni2 = ((MemtreeNodeIdentity) args[0]);
398. 
399.                     final Optional<Boolean> niEquals = ni1.getNodeId().flatMap(n1id -> ni2.getNodeId().map(n2id -> n1id._1 == n2id._1 && n1id._2 == n2id._2 && n1id._3 == n2id._3));
400.                     if (niEquals.isPresent()) {
401.                         domResult = niEquals.get();
402.                     }
403.             } else if(method.getName().equals("getNodeId")) {
404.                 if (obj instanceof StoredNodeIdentity
405.                         && args.length == 0
406.                         && node instanceof StoredNode) {
407.                     domResult = Optional.of(((StoredNode) node).getNodeId());
408.                 } else if (obj instanceof MemtreeNodeIdentity
409.                         && args.length == 0
410.                         && node instanceof org.exist.dom.memtree.NodeImpl) {
411.                     final org.exist.dom.memtree.NodeImpl memtreeNode = (org.exist.dom.memtree.NodeImpl) node;
412.                     domResult = Optional.of(Tuple(memtreeNode.getOwnerDocument(), memtreeNode.getNodeNumber(), memtreeNode.getNodeType()));
413.                 } else {
414.                     domResult = Optional.empty();
415.                 }
416.             }
417. 
418.             if (domResult == null) {
419.                 domResult = method.invoke(node, args);
420.             }
421. 
422.             if(domResult != null && Node.class.isAssignableFrom(method.getReturnType())) {
423.                 return exportInternalNode((Node) domResult); //recursively wrap node result
424. 
425.             } else if(domResult != null && method.getReturnType().equals(NodeList.class)) {
426.                 final NodeList underlying = (NodeList)domResult; //recursively wrap nodes in nodelist result
427.                 return new NodeList() {
428.                     @Override
429.                     public Node item(final int index) {
430.                         return Optional.ofNullable(underlying.item(index))
431.                                 .map(LocalXMLResource.this::exportInternalNode)
432.                                 .orElse(null);
433.                     }
434. 
435.                     @Override
436.                     public int getLength() {
437.                         return underlying.getLength();
438.                     }
439.                 };
440.             } else {
441.                 return domResult;
442.             }
443.         }
444.     }
