454.     /**
455.      * Used by {@link DOMMethodInterceptor} to
456.      * help with equality of memtree DOM nodes.
457.      */
458.     private interface MemtreeNodeIdentity {
459.         Optional<Tuple3<DocumentImpl, Integer, Short>> getNodeId();
460.     }
