462.     @Override
463.     public void getContentAsSAX(final ContentHandler handler) throws XMLDBException {
464. 
465.         // case 1: content is an external DOM node
466.         if (root != null && !(root instanceof NodeValue)) {
467.             try {
468.                 final String option = collection.getProperty(Serializer.GENERATE_DOC_EVENTS, "false");
469.                 final DOMStreamer streamer = (DOMStreamer) SerializerPool.getInstance().borrowObject(DOMStreamer.class);
470.                 try {
471.                     streamer.setContentHandler(handler);
472.                     streamer.setLexicalHandler(lexicalHandler);
473.                     streamer.serialize(root, option.equalsIgnoreCase("true"));
474.                 } finally {
475.                     SerializerPool.getInstance().returnObject(streamer);
476.                 }
477.             } catch (final Exception e) {
478.                 throw new XMLDBException(ErrorCodes.INVALID_RESOURCE, e.getMessage(), e);
479.             }
480.         } else {
481.             withDb((broker, transaction) -> {
482.                 try {
483.                     // case 2: content is an atomic value
484.                     if (value != null) {
485.                         value.toSAX(broker, handler, getProperties());
486. 
487.                     // case 3: content is an internal node or a document
488.                     } else {
489.                         final Serializer serializer = broker.borrowSerializer();
490.                         try {
491.                             serializer.setUser(user);
492.                             serializer.setProperties(getProperties());
493.                             serializer.setSAXHandlers(handler, lexicalHandler);
494.                             if (root != null) {
495.                                 serializer.toSAX((NodeValue) root);
496. 
497.                             } else if (proxy != null) {
498.                                 serializer.toSAX(proxy);
499. 
500.                             } else {
501.                                 read(broker, transaction).apply((document, broker1, transaction1) -> {
502.                                     try {
503.                                         serializer.toSAX(document);
504.                                         return null;
505.                                     } catch (final SAXException e) {
506.                                         throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
507.                                     }
508.                                 });
509.                             }
510.                         } finally {
511.                             broker.returnSerializer(serializer);
512.                         }
513.                     }
514.                     return null;
515.                 } catch(final SAXException e) {
516.                     throw new XMLDBException(ErrorCodes.VENDOR_ERROR, e.getMessage(), e);
517.                 }
518.             });
519.         }
520.     }
