522.     /**
523.      * Sets the content for this resource. If value is of type File, it is
524.      * directly passed to the parser when Collection.storeResource is called.
525.      * Otherwise the method tries to convert the value to String.
526.      * 
527.      * Passing a File object should be preferred if the document is large. The
528.      * file's content will not be loaded into memory but directly passed to a
529.      * SAX parser.
530.      * 
531.      * @param obj the content value to set for the resource.
532.      * @throws XMLDBException with expected error codes. See {@link ErrorCodes#VENDOR_ERROR}
533.      *     for any vendor specific errors that occur.
534.      */
535.     @Override
536.     public void setContent(final Object obj) throws XMLDBException {
537.         content = null;
538.         file = null;
539.         value = null;
540.         inputSource = null;
541.         root = null;
542. 
543.         if (obj instanceof Path) {
544.             file = (Path) obj;
545.         } else if (obj instanceof java.io.File) {
546.             file = ((java.io.File) obj).toPath();
547.         } else if (obj instanceof AtomicValue) {
548.             value = (AtomicValue) obj;
549.         } else if (obj instanceof InputSource) {
550.             inputSource=(InputSource) obj;
551.         } else if (obj instanceof byte[]) {
552.             content = new String((byte[])obj, UTF_8);
553.         } else {
554.             content = obj.toString();
555.         }
556.     }
