412.      * Define a primitive type.
413.      *
414.      * @param primitiveType the primitive type
415.      * @param subTypes the subtypes of the primitive type
416.      */
417.     private static void definePrimitiveType(final int primitiveType, final int... subTypes) {
418.         for (final int subType : subTypes) {
419.             primitiveTypes.put(subType, primitiveType);
420.         }
421. 
422.         // primitive type of a primitive type is itself!
423.         primitiveTypes.put(primitiveType, primitiveType);
