426.     /**
427.      * Get the internal default name for the built-in type.
428.      *
429.      * @param type the type constant
430.      * @return name of the type
431.      */
432.     public static @Nullable String getTypeName(final int type) {
433.         final String[] names = typeNames.get(type);
434.         if (names != null) {
435.             return names[0];
436.         }
437.         return null;
