442.      *
443.      * @param type the type constant
444.      * @return one or more alias names
445.      */
446.     public static @Nullable String[] getTypeAliases(final int type) {
447.         final String names[] = typeNames.get(type);
448.         if (names != null && names.length > 1) {
449.             final String aliases[] = new String[names.length - 1];
450.             System.arraycopy(names, 1, aliases, 0, names.length - 1);
451.             return aliases;
