456.     /**
457.      * Get the type code for a type identified by its internal name.
458.      *
459.      * @param name name of the type
460.      * @return type constant
461.      * @throws XPathException in case of dynamic error
462.      */
463.     public static int getType(final String name) throws XPathException {
464.         final int code = typeCodes.getInt(name);
465.         if (code == NO_SUCH_VALUE) {
466.             throw new XPathException((Expression) null, "Type: " + name + " is not defined");
467.         }
468.         return code;
469.     }
