471.     /**
472.      * Get the type code for a type identified by its QName.
473.      *
474.      * @param qname name of the type
475.      * @return type constant
476.      * @throws XPathException in case of dynamic error
477.      */
478.     public static int getType(final QName qname) throws XPathException {
479.         final String uri = qname.getNamespaceURI();
480.         switch (uri) {
481.             case Namespaces.SCHEMA_NS:
482.                 return getType("xs:" + qname.getLocalPart());
483.             case Namespaces.XPATH_DATATYPES_NS:
484.                 return getType("xdt:" + qname.getLocalPart());
485.             default:
486.                 return getType(qname.getLocalPart());
487.         }
488.     }
