490.     /**
491.      * Check if the given type code is a subtype of the specified supertype.
492.      *
493.      * @param subtype the type constant of the subtype
494.      * @param supertype type constant of the super type
495.      *
496.      * @return true if subtype is a sub type of supertype
497.      *
498.      * @throws IllegalArgumentException When the type is invalid
499.      */
500.     public static boolean subTypeOf(int subtype, final int supertype) {
501.         if (subtype == supertype) {
502.             return true;
503.         }
504. 
505.         if (supertype == ITEM || supertype == ANY_TYPE) {
506.             // Note: this will return true even if subtype == EMPTY, maybe return subtype != EMPTY ?
507.             return true;
508.         }
509. 
510.         // Note that EMPTY is *not* a sub-type of anything else than itself
511.         // EmptySequence has to take care of this when it checks its type
512.         if (subtype == ITEM || subtype == EMPTY || subtype == ANY_TYPE || subtype == NODE) {
513.             return false;
514.         }
515. 
516.         if (unionTypes.containsKey(supertype)) {
517.             return subTypeOfUnion(subtype, supertype);
518.         }
519.         if (unionTypes.containsKey(subtype)) {
520.             return unionMembersHaveSuperType(subtype, supertype);
521.         }
522. 
523.         subtype = superTypes[subtype];
524.         if (subtype == 0) {
525.             throw new IllegalArgumentException(
526.                     "type " + subtype + " is not a valid type");
527.         }
528.         return subTypeOf(subtype, supertype);
529.     }
530. 
531.     /**
532.      * Get the type code of the supertype of the specified subtype.
533.      *
534.      * @param subtype type code of the sub type
535.      * @return type constant for the super type
536.      */
537.     public static int getSuperType(final int subtype) {
538.         if (subtype == ITEM || subtype == NODE) {
539.             return ITEM;
540.         } else if (subtype == ANY_TYPE) {
541.             return subtype;
542.         }
543. 
544.         final int supertype = superTypes[subtype];
545.         if (supertype == 0) {
546.             LOG.warn("eXist-db does not define a super-type for the sub-type {}", getTypeName(subtype), new Throwable());
547.             return ITEM;
548.         }
549. 
550.         return supertype;
551.     }
552. 
553.     /**
554.      * Find a common supertype for two given type codes.
555.      *
556.      * Type.ITEM is returned if no other common supertype
557.      * is found.
558.      *
559.      * @param type1 type constant for the first type
560.      * @param type2 type constant for the second type
561.      * @return common super type or {@link Type#ITEM} if none
562.      */
563.     public static int getCommonSuperType(final int type1, final int type2) {
564.         //Super shortcut
565.         if (type1 == type2) {
566.             return type1;
567.         }
568.         // if one of the types is empty(), return the other type: optimizer is free to choose
569.         // an optimization based on the more specific type.
570.         if (type1 == Type.EMPTY) {
571.             return type2;
572.         } else if (type2 == Type.EMPTY) {
573.             return type1;
574.         }
575. 
576.         //TODO : optimize by swapping the arguments based on their numeric values ?
577.         //Processing lower value first *should* reduce the size of the Set
578.         //Collect type1's super-types
579.         final IntSet t1 = new IntOpenHashSet(Hash.DEFAULT_INITIAL_SIZE, Hash.VERY_FAST_LOAD_FACTOR);
580.         //Don't introduce a shortcut (starting at getSuperType(type1) here
581.         //type2 might be a super-type of type1
582.         int t;
583.         for (t = type1; t != ITEM && t != ANY_TYPE; t = getSuperType(t)) {
584.             //Shortcut
585.             if (t == type2) {
586.                 return t;
587.             }
588.             t1.add(t);
589.         }
590.         //Starting from type2's super type : the shortcut should have done its job
591.         for (t = getSuperType(type2); t != ITEM && t != ANY_TYPE; t = getSuperType(t)) {
592.             if (t1.contains(t)) {
593.                 return t;
594.             }
595.         }
596.         return t;
597.     }
598. 
599.     /**
600.      * Determines if a union type has an other type as a member.
601.      *
602.      * @param unionType the union type
603.      * @param other the type to test for union membership
604.      *
605.      * @return true if the type is a member, false otherwise.
606.      */
607.     public static boolean hasMember(final int unionType, final int other) {
608.         final IntArraySet members = unionTypes.get(unionType);
609.         if (members == null) {
610.             return false;
611.         }
612.         return members.contains(other);
613.     }
614. 
615.     /**
616.      * Check if the given type is a subtype of a member of the specified union type.
617.      *
618.      * @param subtype the type constant of the subtype
619.      * @param unionType the union type
620.      *
621.      * @return true if subtype is a sub type of a member of the union type
622.      */
623.     public static boolean subTypeOfUnion(final int subtype, final int unionType) {
624.         final IntArraySet members = unionTypes.get(unionType);
625.         if (members == null) {
626.             return false;
627.         }
628. 
629.         // inherited behaviour from {@link #subTypeOf(int, int)}
630.         // where type is considered a subtype of itself.
631.         if (subtype == unionType) {
632.             return true;
633.         }
634. 
635.         // quick optimisation for: subtype = member
636.         if (members.contains(subtype)) {
637.             return true;
638.         }
639. 
640.         for (final int member : members) {
641.             if (subTypeOf(subtype, member)) {
642.                 return true;
643.             }
644.         }
645.         return false;
646.     }
647. 
648.     public static boolean unionMembersHaveSuperType(final int unionType, final int supertype) {
649.         final IntArraySet members = unionTypes.get(unionType);
650.         if (members == null || members.size() == 0) {
651.             return false;
652.         }
653. 
654.         // inherited behaviour from {@link #subTypeOf(int, int)}
655.         // where type is considered a subtype of itself.
656.         if (supertype == unionType) {
657.             return true;
658.         }
659. 
660.         for (final int member : members) {
661.             if (!subTypeOf(member, supertype)) {
662.                 return false;
663.             }
664.         }
665. 
666.         return true;
667.     }
668. 
669.     /**
670.      * Gets the primitive type for a typed atomic type.
671.      *
672.      * @param type the type to retrieve the primitive type of
673.      *
674.      * @return the primitive type
675.      *
676.      * @throws IllegalArgumentException if {@code type} has no defined primitive type
677.      */
678.     public static int primitiveTypeOf(final int type) throws IllegalArgumentException {
679.         final int primitiveType = primitiveTypes.get(type);
680.         if (primitiveType == NO_SUCH_VALUE) {
681.             final String typeName = getTypeName(type);
682.             throw new IllegalArgumentException("Primitive type is not defined for: " + (typeName != null ? typeName : type));
683.         }
684.         return primitiveType;
685.     }
686. }
